class BaseReport {}

class SalesReport extends BaseReport {
  generate() {
    const rows = this.fetchRows();
    return rows.map(r => `${r.id}:${r.value}`).join('\n');
  }
}

class InventoryReport extends BaseReport {
  generate() {
    const rows = this.fetchRows();
    return rows.map(r => `${r.id}:${r.value}`).join('\n');
  }
}

abstract class Invoice {
  items: number[];
  constructor(items: number[]) { this.items = items }
}

class RetailInvoice extends Invoice {
  calculateTotal() {
    const sum = this.items.reduce((a, b) => a + b, 0);
    return sum * 1.10 + this.getRetailDiscount();
  }
}

class WholesaleInvoice extends Invoice {
  calculateTotal() {
    const sum = this.items.reduce((a, b) => a + b, 0);
    return sum * 1.05 + this.getWholesaleDiscount();
  }
}

